    'split.processing': 'Extrayendo Páginas...',
    'split.rangeHint': 'Usa guiones para rangos (ej. 1-5) y comas para páginas individuales (ej. 1, 3, 7).',
    'split.rangeLabel': 'Rango de Páginas a Extraer',
    'split.rangePlaceholder': 'ej. 1-3, 5, 8-10',
    'split.subtitle': 'Selecciona números de página o rangos exactos para extraer en un archivo PDF separado. Se ejecuta completamente en tu navegador.',
    'split.totalPages': 'Páginas Totales',
    'terms.s1.body': 'Al acceder o usar RealEditPDF, aceptas estar sujeto a estos Términos y Condiciones. Si no estás de acuerdo con alguna parte de estos términos, no puedes acceder al servicio.',
    'terms.s1.title': '1. Aceptación de los Términos',
    'terms.s2.title': '2. Propiedad del Usuario y Derechos Comerciales',
    'terms.s2.body': 'RealEditPDF funciona completamente dentro de tu navegador web utilizando WebAssembly y JavaScript del lado del cliente. No almacenamos, visualizamos, transmitimos ni reclamamos propiedad alguna sobre los documentos que subes, editas o creas. Conservas el 100% de la propiedad, derechos de autor y derechos comerciales sobre todos los archivos originales, documentos editados, firmas y archivos exportados creados con el servicio. Eres libre de usar, modificar, distribuir y monetizar comercialmente cualquier documento procesado a través de RealEditPDF sin regalías ni restricciones.',
    'terms.s3.body': 'Los materiales en el sitio web de RealEditPDF se proporcionan \'tal cual\'. RealEditPDF no ofrece garantías, expresas o implícitas, y por la presente renuncia y niega todas las demás garantías, incluyendo sin limitación, garantías implícitas o condiciones de comerciabilidad, idoneidad para un propósito particular, o no infracción de propiedad intelectual. RealEditPDF no garantiza ni hace ninguna representación sobre la precisión, resultados probables o confiabilidad del uso de los materiales en su sitio web.',
    'terms.s3.title': '3. Exención de Responsabilidad',
    'terms.s4.body': 'En ningún caso RealEditPDF o sus proveedores serán responsables de ningún daño (incluyendo, sin limitación, daños por pérdida de datos o ganancias, o debido a la interrupción del negocio) que surja del uso o la imposibilidad de usar los materiales en el sitio web de RealEditPDF, incluso si RealEditPDF o un representante autorizado de RealEditPDF ha sido informado de la posibilidad de tales daños.',
    'terms.s4.title': '4. Limitación de Responsabilidad',
    'terms.s5.body': 'Los materiales en el sitio web de RealEditPDF podrían incluir errores técnicos, tipográficos o fotográficos. RealEditPDF no garantiza que ninguno de los materiales en su sitio web sea preciso, completo o actual. RealEditPDF puede hacer cambios a los materiales contenidos en su sitio web en cualquier momento sin previo aviso. Sin embargo, RealEditPDF no se compromete a actualizar los materiales.',
    'terms.s5.title': '5. Revisiones y Erratas',
    'terms.subtitle': 'Por favor lee estos Términos y Condiciones cuidadosamente antes de usar los servicios de RealEditPDF.',
