    'terms.s2.body': 'RealEditPDF は、クライアント側の WebAssembly と JavaScript を使用してブラウザ内で完全に動作します。アップロード、編集、作成されたドキュメントを当社が保存、閲覧、送信、または所有権を主張することはありません。お客様は、本サービスを使用して作成されたすべての元ファイル、編集済みドキュメント、電子署名、およびエクスポートされたアセットに対して 100% の所有権、著作権、および商用利用権を保持します。ロイヤリティや制限なしに、RealEditPDF で処理されたすべてのドキュメントを自由に使用、変更、配布、および商用利用することができます。',
    'terms.s3.body': 'RealEditPDF のウェブサイト上のマテリアルは「現状のまま」提供されます。RealEditPDF は、明示的または黙示的を問わず、いかなる保証も行わず、市場性、特定目的への適合性、または知的財産の非侵害の黙示的保証または条件を含むがこれらに限定されない、他のすべての保証をここに放棄および否定します。RealEditPDF は、そのインターネットウェブサイト上のマテリアルの使用に関する正確性、可能性のある結果、または信頼性について保証または表明を行いません。',
