    '500.untouchedBody': 'RealEditPDF fonctionne entièrement dans votre navigateur en utilisant WebAssembly. Une erreur de serveur comme celle-ci signifie seulement que notre edge n\'a pas pu rendre la page — vos PDF, signatures et modifications vivent sur votre appareil, intacts.',
    'about.how.s1': 'Téléversez votre PDF directement dans votre navigateur',
    'about.how.s2': 'Le traitement se fait entièrement sur votre appareil avec WebAssembly',
