    'about.how.title': 'Comment Ça Marche',
    'about.mission.body': 'Fournir un studio PDF qui permet aux particuliers et aux organisations de travailler avec des documents en toute sécurité. Nous croyons que vos fichiers ne devraient jamais quitter votre appareil, et qu\'aucun tiers ne devrait avoir accès à vos informations sensibles.',
