    'about.privacy.title': 'Promesse de Confidentialité',
    'about.subtitle': 'RealEditPDF a été conçu avec la confidentialité comme principe fondamental. Contrairement aux éditeurs PDF en ligne traditionnels qui nécessitent de téléverser vos documents vers des serveurs cloud distants, nous exécutons l\'intégralité du moteur de traitement PDF localement dans votre navigateur en utilisant WebAssembly.',
