    'footer.status': '100% WebAssembly Côté Client',
    'footer.tagline': 'Le studio PDF ultime côté client. Éditez du texte, dessinez, signez, masquez, réorganisez, fusionnez et divisez des PDF en toute confidentialité. Pas de limites quotidiennes, pas de péages et zéro téléversement serveur.',
    'hero.badge': '100% Privé WASM dans le Navigateur',
