    'hero.noSize': 'Aucune Limite de Taille',
    'home.bento1Body': 'Ajoutez du nouveau texte n\'importe où avec une typographie, des polices, des couleurs et des tailles de police personnalisées. Couvrez et écrasez en toute transparence le texte existant du document en utilisant la fonction de fond whiteout.',
    'home.bento1Cta': 'Contrôle de Typographie en Ligne',
    'home.bento1Title': 'Édition de Texte et Whiteout Intelligent',
    'home.bento2Body': 'Dessinez des signatures fluides, tapez des scripts de calligraphie, ou téléversez votre image de signature avec suppression automatique de la transparence du fond blanc.',
    'home.bento2Cta': 'Dessiner • Taper • Téléverser',
    'home.bento2Title': 'Signature Électronique et Initiales',
    'home.bento3Body': 'Masquez les numéros de sécurité sociale sensibles, les dossiers médicaux ou les prix confidentiels. Efface définitivement les données avant l\'exportation.',
    'home.bento3Cta': 'Caviardage Irréversible',
    'home.bento3Title': 'Masquage Permanent',
    'home.bento4Body': 'Pivotez des pages individuelles ou par lots de 90°, supprimez les pages indésirables, dupliquez les feuilles importantes et insérez des pages vierges à la volée avec des cartes d\'aperçu visuel en direct.',
    'home.bento4Cta': 'Réorganiser • Pivoter • Dupliquer',
    'home.bento4Title': 'Organisateur de Pages et Studio de Miniatures',
    'home.bento5Body': 'Crayon libre et fluide pour marquer les documents, ainsi que des surligneurs semi-transparents avec épaisseur de trait personnalisable.',
    'home.bento5Cta': 'Toile de Dessin Vectoriel',
    'home.bento5Title': 'Dessiner et Surligner',
