    'split.errorEmptyRange': 'Veuillez entrer des numéros de page valides.',
    'split.errorPrefix': 'Échec de la division : ',
    'split.execute': 'Extraire les Pages et Télécharger PDF',
    'split.processing': 'Extraction des pages...',
    'split.rangeHint': 'Utilisez des traits d\'union pour les plages (ex. 1-5) et des virgules pour les pages individuelles (ex. 1, 3, 7).',
    'split.rangeLabel': 'Plage de Pages à Extraire',
    'split.rangePlaceholder': 'ex. 1-3, 5, 8-10',
    'split.subtitle': 'Sélectionnez des numéros de page ou des plages exactes à extraire dans un fichier PDF séparé. Fonctionne entièrement dans votre navigateur.',
    'split.totalPages': 'Pages Totales',
    'terms.s1.body': 'En accédant ou en utilisant RealEditPDF, vous acceptez d\'être lié par ces Conditions Générales. Si vous n\'êtes pas d\'accord avec une partie de ces conditions, vous ne pouvez pas accéder au service.',
    'terms.s1.title': '1. Acceptation des Conditions',
    'terms.s2.title': '2. Propriété de l\'Utilisateur et Droits Commerciaux',
    'terms.s2.body': 'RealEditPDF fonctionne entièrement dans votre navigateur Web à l\'aide de WebAssembly et de JavaScript côté client. Nous ne stockons, ne visualisons, ne transmettons et ne revendiquons aucune propriété sur les documents que vous téléversez, modifiez ou créez. Vous conservez 100 % de la propriété, des droits d\'auteur et des droits commerciaux sur tous les fichiers originaux, documents modifiés, signatures et ressources exportées produits à l\'aide du service. Vous êtes libre d\'utiliser, de modifier, de distribuer et d\'exploiter commercialement tout document traité via RealEditPDF sans redevances ni restrictions.',
    'terms.s3.body': 'Les matériaux sur le site Web de RealEditPDF sont fournis \'en l\'état\'. RealEditPDF n\'offre aucune garantie, expresse ou implicite, et décline par la présente toute autre garantie, y compris sans limitation, les garanties implicites ou conditions de qualité marchande, d\'adéquation à un usage particulier, ou de non-violation de la propriété intellectuelle. RealEditPDF ne garantit ni ne fait aucune représentation concernant l\'exactitude, les résultats probables ou la fiabilité de l\'utilisation des matériaux sur son site Web.',
    'terms.s3.title': '3. Avis de Non-Responsabilité',
    'terms.s4.body': 'En aucun cas RealEditPDF ou ses fournisseurs ne seront responsables de tout dommage (y compris, sans limitation, les dommages pour perte de données ou de profit, ou en raison d\'une interruption d\'activité) découlant de l\'utilisation ou de l\'impossibilité d\'utiliser les matériaux sur le site Web de RealEditPDF, même si RealEditPDF ou un représentant autorisé de RealEditPDF a été informé de la possibilité de tels dommages.',
    'terms.s4.title': '4. Limitation de Responsabilité',
    'terms.s5.body': 'Les matériaux sur le site Web de RealEditPDF peuvent inclure des erreurs techniques, typographiques ou photographiques. RealEditPDF ne garantit pas que les matériaux sur son site Web sont exacts, complets ou à jour. RealEditPDF peut apporter des modifications aux matériaux contenus sur son site Web à tout moment sans préavis. Cependant, RealEditPDF ne s\'engage pas à mettre à jour les matériaux.',
    'terms.s5.title': '5. Révisions et Errata',
    'terms.subtitle': 'Veuillez lire attentivement ces Conditions Générales avant d\'utiliser les services RealEditPDF.',
