    'about.how.title': 'Wie es funktioniert',
    'about.mission.body': 'Ein PDF-Studio bereitzustellen, das Einzelpersonen und Organisationen ermöglicht, sicher mit Dokumenten zu arbeiten. Wir glauben, dass Ihre Dateien Ihr Gerät nie verlassen sollten und kein Dritter Zugriff auf Ihre sensiblen Informationen haben sollte.',
