    'about.subtitle': 'RealEditPDF wurde mit Privatsphäre als Grundprinzip entwickelt. Im Gegensatz zu herkömmlichen Online-PDF-Editoren, die erfordern, dass Sie Ihre Dokumente auf entfernte Cloud-Server hochladen, führen wir die gesamte PDF-Verarbeitungs-Engine lokal in Ihrem Browser mit WebAssembly aus.',
