    'home.bento4Body': 'Drehen Sie einzelne oder Batch-Seiten um 90°, löschen Sie unerwünschte Seiten, duplizieren Sie wichtige Blätter und fügen Sie leere Seiten spontan mit Live-Visual-Vorschau-Karten ein.',
