    'home.bento4Title': 'Seiten-Organisator & Thumbnail-Studio',
    'home.bento5Body': 'Sanfter Freihandstift zum Markieren von Dokumenten, zusammen mit halbtransparenten Markern mit anpassbarer Strichstärke.',
