    'split.execute': 'Seiten extrahieren & PDF herunterladen',
    'split.processing': 'Seiten werden extrahiert...',
    'split.rangeHint': 'Verwenden Sie Bindestriche für Bereiche (z.B. 1-5) und Kommas für einzelne Seiten (z.B. 1, 3, 7).',
    'split.rangeLabel': 'Zu extrahierender Seitenbereich',
