    'split.subtitle': 'Wählen Sie genaue Seitenzahlen oder Bereiche aus, die in eine separate PDF-Datei extrahiert werden sollen. Läuft vollständig in Ihrem Browser.',
    'split.totalPages': 'Gesamtseiten',
    'terms.s1.body': 'Durch den Zugriff auf oder die Nutzung von RealEditPDF erklären Sie sich an diese Allgemeinen Geschäftsbedingungen gebunden. Wenn Sie mit irgendeinem Teil dieser Bedingungen nicht einverstanden sind, dürfen Sie den Dienst nicht nutzen.',
    'terms.s1.title': '1. Annahme der Bedingungen',
    'terms.s2.title': '2. Eigentum des Nutzers und kommerzielle Rechte',
    'terms.s2.body': 'RealEditPDF arbeitet vollständig in Ihrem Webbrowser mithilfe clientseitiger WebAssembly und JavaScript. Wir speichern, überprüfen, übertragen oder beanspruchen keinerlei Eigentum an den Dokumenten, die Sie hochladen, bearbeiten oder erstellen. Sie behalten 100 % des Eigentums, der Urheberrechte und der kommerziellen Rechte an allen Originaldateien, bearbeiteten Dokumenten, Signaturen und exportierten Dateien, die mit dem Dienst erstellt wurden. Sie können alle mit RealEditPDF verarbeiteten Dokumente ohne Lizenzgebühren oder Einschränkungen frei verwenden, ändern, verteilen und kommerziell verwerten.',
    'terms.s3.body': 'Die Materialien auf der RealEditPDF-Website werden \'wie besehen\' bereitgestellt. RealEditPDF gibt keine Garantien, weder ausdrücklich noch implizit, und lehnt hiermit alle anderen Garantien ab, einschließlich ohne Einschränkung impliziter Garantien oder Bedingungen der Marktgängigkeit, Eignung für einen bestimmten Zweck oder Nichtverletzung geistigen Eigentums. RealEditPDF garantiert oder macht keine Zusicherungen bezüglich der Genauigkeit, wahrscheinlichen Ergebnisse oder Zuverlässigkeit der Nutzung der Materialien auf seiner Internet-Website.',
    'terms.s3.title': '3. Haftungsausschluss',
    'terms.s4.body': 'In keinem Fall haften RealEditPDF oder seine Lieferanten für Schäden (einschließlich, ohne Einschränkung, Schäden für Daten- oder Gewinnverlust oder aufgrund von Geschäftsunterbrechung), die sich aus der Nutzung oder Unfähigkeit zur Nutzung der Materialien auf der RealEditPDF-Website ergeben, selbst wenn RealEditPDF oder ein autorisierter Vertreter von RealEditPDF auf die Möglichkeit solcher Schäden hingewiesen wurde.',
    'terms.s4.title': '4. Haftungsbeschränkung',
    'terms.s5.body': 'Die Materialien auf der RealEditPDF-Website können technische, typografische oder fotografische Fehler enthalten. RealEditPDF garantiert nicht, dass die Materialien auf seiner Website genau, vollständig oder aktuell sind. RealEditPDF kann jederzeit ohne Vorankündigung Änderungen an den Materialien auf seiner Website vornehmen. RealEditPDF verpflichtet sich jedoch nicht, die Materialien zu aktualisieren.',
    'terms.s5.title': '5. Überarbeitungen und Errata',
    'terms.subtitle': 'Bitte lesen Sie diese Allgemeinen Geschäftsbedingungen sorgfältig, bevor Sie die RealEditPDF-Dienste nutzen.',
