    '500.untouchedBody': 'O RealEditPDF é executado inteiramente no seu navegador usando WebAssembly. Um erro de servidor como este significa apenas que nossa edge não conseguiu renderizar a página — seus PDFs, assinaturas e edições vivem no seu dispositivo, intactos.',
