    'about.how.title': 'Como Funciona',
    'about.mission.body': 'Fornecer um estúdio de PDF que capacita indivíduos e organizações a trabalhar com documentos com segurança. Acreditamos que seus arquivos nunca devem sair do seu dispositivo, e que nenhum terceiro deve ter acesso às suas informações sensíveis.',
