    'footer.status': '100% WebAssembly do Lado do Cliente',
    'footer.tagline': 'O estúdio definitivo de PDF do lado do cliente. Edite texto, desenhe, assine, oculte, reordene, mescle e divida PDFs com privacidade completa. Sem limites diários, sem paywalls e zero uploads para servidor.',
