    'hero.noSize': 'Sem Limites de Tamanho',
    'home.bento1Body': 'Adicione novo texto em qualquer lugar com tipografia, fontes, cores e tamanhos de fonte personalizados. Cubra e sobrescreva perfeitamente o texto existente do documento usando o recurso de fundo whiteout.',
    'home.bento1Cta': 'Controle de Tipografia Inline',
    'home.bento1Title': 'Edição de Texto e Whiteout Inteligente',
    'home.bento2Body': 'Desenhe assinaturas suaves, digite scripts de caligrafia ou faça upload da sua imagem de assinatura com remoção automática de transparência do fundo branco.',
    'home.bento2Cta': 'Desenhar • Digitar • Upload',
    'home.bento2Title': 'Assinatura Eletrônica e Iniciais',
    'home.bento3Body': 'Bloqueie números sensíveis de seguro social, registros médicos ou preços confidenciais. Apaga permanentemente os dados antes da exportação.',
    'home.bento3Cta': 'Bloqueio Irreversível',
    'home.bento3Title': 'Ocultação Permanente',
    'home.bento4Body': 'Gire páginas individuais ou em lote 90°, exclua páginas indesejadas, duplique folhas importantes e insira páginas em branco dinamicamente com cartões de visualização ao vivo.',
    'home.bento4Cta': 'Reordenar • Girar • Duplicar',
