    'images.subtitle': 'Extraia cada página do seu PDF como arquivos de imagem claros de 300 DPI. Recorte e redimensione qualquer imagem de página diretamente antes ou depois do download.',
    'lang.switchTo': 'Mudar para',
    'merge.addMore': '+ Adicionar Mais PDFs',
