    'split.errorPrefix': 'Falha ao dividir: ',
    'split.execute': 'Extrair Páginas e Baixar PDF',
    'split.processing': 'Extraindo páginas...',
    'split.rangeHint': 'Use hifens para intervalos (ex. 1-5) e vírgulas para páginas individuais (ex. 1, 3, 7).',
    'split.rangeLabel': 'Intervalo de Páginas a Extrair',
    'split.rangePlaceholder': 'ex. 1-3, 5, 8-10',
    'split.subtitle': 'Selecione números de página ou intervalos exatos para extrair em um arquivo PDF separado. Executa completamente no seu navegador.',
    'split.totalPages': 'Total de Páginas',
    'terms.s1.body': 'Ao acessar ou usar o RealEditPDF, você concorda em ficar vinculado a estes Termos e Condições. Se você discordar de qualquer parte destes termos, não poderá acessar o serviço.',
    'terms.s1.title': '1. Aceitação dos Termos',
    'terms.s2.title': '2. Propriedade do Usuário e Direitos Comerciais',
    'terms.s2.body': 'O RealEditPDF opera inteiramente no seu navegador da web usando WebAssembly e JavaScript no lado do cliente. Não armazenamos, visualizamos, transmitimos ou reivindicamos qualquer propriedade sobre os documentos que você envia, edita ou cria. Você retém 100% da propriedade, direitos autorais e direitos comerciais sobre todos os arquivos originais, documentos editados, assinaturas e ativos exportados gerados usando o serviço. Você é livre para usar, modificar, distribuir e monetizar comercialmente quaisquer documentos processados pelo RealEditPDF sem royalties ou restrições.',
    'terms.s3.body': 'Os materiais no site do RealEditPDF são fornecidos \'como estão\'. O RealEditPDF não oferece garantias, expressas ou implícitas, e por meio desta isenta e nega todas as outras garantias, incluindo, sem limitação, garantias implícitas ou condições de comercialização, adequação a uma finalidade específica ou não violação de propriedade intelectual. O RealEditPDF não garante nem faz representações sobre a precisão, resultados prováveis ou confiabilidade do uso dos materiais em seu site.',
    'terms.s3.title': '3. Isenção de Responsabilidade',
    'terms.s4.body': 'Em nenhum caso o RealEditPDF ou seus fornecedores serão responsáveis por quaisquer danos (incluindo, sem limitação, danos por perda de dados ou lucro, ou devido à interrupção de negócios) decorrentes do uso ou incapacidade de usar os materiais no site do RealEditPDF, mesmo se o RealEditPDF ou um representante autorizado do RealEditPDF tiver sido avisado da possibilidade de tais danos.',
    'terms.s4.title': '4. Limitação de Responsabilidade',
    'terms.s5.body': 'Os materiais no site do RealEditPDF podem incluir erros técnicos, tipográficos ou fotográficos. O RealEditPDF não garante que qualquer um dos materiais em seu site seja preciso, completo ou atual. O RealEditPDF pode fazer alterações nos materiais contidos em seu site a qualquer momento sem aviso prévio. No entanto, o RealEditPDF não se compromete a atualizar os materiais.',
    'terms.s5.title': '5. Revisões e Erratas',
    'terms.subtitle': 'Por favor, leia estes Termos e Condições cuidadosamente antes de usar os serviços do RealEditPDF.',
