    'split.downloadName': '추출된-페이지-{range}.pdf',
    'split.errorEmptyRange': '유효한 페이지 번호를 입력하세요.',
    'split.errorPrefix': '분할 실패: ',
    'split.execute': '페이지 추출 및 PDF 다운로드',
    'split.processing': '페이지 추출 중...',
    'split.rangeHint': '범위에는 하이픈(예: 1-5), 개별 페이지에는 쉼표(예: 1, 3, 7)를 사용하세요.',
    'split.rangeLabel': '추출할 페이지 범위',
    'split.rangePlaceholder': '예: 1-3, 5, 8-10',
    'split.subtitle': '별도 PDF 파일로 추출할 정확한 페이지 번호 또는 범위를 선택하세요. 브라우저에서 완전히 실행됩니다.',
    'split.totalPages': '총 페이지',
    'terms.s1.body': 'RealEditPDF에 액세스하거나 사용함으로써 이 이용약관에 구속되는 것에 동의합니다. 이 약관의 어떤 부분에든 동의하지 않으면 서비스에 액세스할 수 없습니다.',
    'terms.s1.title': '1. 약관 동의',
    'terms.s2.title': '2. 사용자 소유권 및 상업적 권리',
    'terms.s2.body': 'RealEditPDF는 클라이언트 측 WebAssembly 및 JavaScript를 사용하여 웹 브라우저 내에서 완전히 실행됩니다. 당사는 귀하가 업로드, 편집 또는 생성하는 문서에 대해 저장, 열람, 전송하거나 어떠한 소유권도 주장하지 않습니다. 귀하는 서비스를 사용하여 제작된 모든 원본 파일, 편집된 문서, 전자서명 및 내보낸 자산에 대해 100%의 소유권, 저작권 및 상업적 권리를 유지합니다. 귀하는 로열티나 제한 없이 RealEditPDF를 통해 처리된 모든 문서를 자유롭게 사용, 수정, 배포 및 상업적으로 활용할 수 있습니다.',
    'terms.s3.body': 'RealEditPDF 웹사이트의 자료는 \'있는 그대로\' 제공됩니다. RealEditPDF는 명시적 또는 묵시적 보증을 제공하지 않으며, 상품성, 특정 목적에의 적합성, 지적 재산권 비침해에 대한 묵시적 보증 또는 조건을 포함하되 이에 국한되지 않는 모든 다른 보증을 본 문서에 의해 부인 및 부인합니다. RealEditPDF는 인터넷 웹사이트의 자료 사용에 대한 정확성, 가능한 결과 또는 신뢰성에 대해 보증하거나 진술하지 않습니다.',
    'terms.s3.title': '3. 면책 조항',
    'terms.s4.body': 'RealEditPDF 또는 그 공급업체는 RealEditPDF 웹사이트의 자료 사용 또는 사용 불능으로 인해 발생하는 모든 손상(데이터 또는 이익 손실, 사업 중단으로 인한 손상을 포함하되 이에 국한되지 않음)에 대해 RealEditPDF 또는 RealEditPDF 공인 대표자가 그러한 손상의 가능성을 통보받은 경우에도 책임을 지지 않습니다.',
    'terms.s4.title': '4. 책임 제한',
    'terms.s5.body': 'RealEditPDF 웹사이트의 자료에는 기술적, 인쇄상 또는 사진상의 오류가 포함될 수 있습니다. RealEditPDF는 웹사이트의 자료가 정확하고 완전하며 최신이라는 것을 보증하지 않습니다. RealEditPDF는 통보 없이 언제든지 웹사이트에 포함된 자료를 변경할 수 있습니다. 그러나 RealEditPDF는 자료를 업데이트할 의무를 지지 않습니다.',
    'terms.s5.title': '5. 수정 및 정오표',
