    'terms.s1.body': 'Accedendo o utilizzando RealEditPDF, accetti di essere vincolato da questi Termini e Condizioni. Se non sei d\'accordo con qualsiasi parte di questi termini, non puoi accedere al servizio.',
    'terms.s1.title': '1. Accettazione dei Termini',
    'terms.s2.title': '2. Proprietà dell\'Utente e Diritti Commerciali',
    'terms.s2.body': 'RealEditPDF funziona interamente all\'interno del tuo browser web utilizzando WebAssembly e JavaScript lato client. Non memorizziamo, visualizziamo, trasmettiamo né rivendichiamo alcuna proprietà sui documenti caricati, modificati o creati. Mantieni il 100% della proprietà, del copyright e dei diritti commerciali su tutti i file originali, documenti modificati, firme e risorse esportate prodotte utilizzando il servizio. Sei libero di utilizzare, modificare, distribuire e monetizzare commercialmente qualsiasi documento elaborato tramite RealEditPDF senza royalty o restrizioni.',
    'terms.s3.body': 'I materiali sul sito web di RealEditPDF sono forniti \'così come sono\'. RealEditPDF non fornisce garanzie, espresse o implicite, e con la presente declina e nega tutte le altre garanzie, incluse senza limitazione, garanzie implicite o condizioni di commerciabilità, idoneità per uno scopo particolare o non violazione di proprietà intellettuale. RealEditPDF non garantisce né rilascia dichiarazioni riguardanti l\'accuratezza, i risultati probabili o l\'affidabilità dell\'uso dei materiali sul suo sito web internet.',
    'terms.s3.title': '3. Esclusione di Responsabilità',
    'terms.s4.body': 'In nessun caso RealEditPDF o i suoi fornitori saranno responsabili per eventuali danni (inclusi, senza limitazione, danni per perdita di dati o profitti, o dovuti a interruzione dell\'attività) derivanti dall\'uso o dall\'impossibilità di utilizzare i materiali sul sito web di RealEditPDF, anche se RealEditPDF o un rappresentante autorizzato di RealEditPDF è stato informato della possibilità di tali danni.',
    'terms.s4.title': '4. Limitazione di Responsabilità',
    'terms.s5.body': 'I materiali sul sito web di RealEditPDF potrebbero includere errori tecnici, tipografici o fotografici. RealEditPDF non garantisce che nessuno dei materiali sul suo sito web sia accurato, completo o attuale. RealEditPDF può apportare modifiche ai materiali contenuti nel suo sito web in qualsiasi momento senza preavviso. Tuttavia, RealEditPDF non si impegna ad aggiornare i materiali.',
    'terms.s5.title': '5. Revisioni ed Errori',
    'terms.subtitle': 'Si prega di leggere attentamente questi Termini e Condizioni prima di utilizzare i servizi RealEditPDF.',
